<?php
if(!defined('ABSPATH')){exit;}
function awsw_icon($name='arrow'){
    $paths=['arrow'=>'<path d="M7 17 17 7M7 7h10v10"/>','chevron'=>'<path d="m6 9 6 6 6-6"/>','food'=>'<path d="M5 4v5m3-5v5m3-5v5M5 9h6m-3 0v11M18 4v16m0-16c-4 2-4 8 0 8"/>','education'=>'<path d="m2 9 10-5 10 5-10 5-10-5Zm4 3v5c4 3 8 3 12 0v-5M22 9v7"/>','water'=>'<path d="M12 3c-2 4-7 8-7 12a7 7 0 0 0 14 0c0-4-5-8-7-12Z"/>','medical'=>'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6V3Z"/>','heart'=>'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 4 12 8 15 4-3 13-10 8-15Z"/>','shield'=>'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>','users'=>'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 5"/>','document'=>'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8"/>','search'=>'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>','close'=>'<path d="m5 5 14 14M19 5 5 19"/>','clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'];
    return '<svg class="awsw-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['arrow']).'</svg>';
}
add_action('init',function(){
    foreach(['member'=>['Team members','Team member'],'photo'=>['Approved gallery','Gallery photo']] as $s=>$l){register_post_type('awsw_'.$s,['labels'=>['name'=>$l[0],'singular_name'=>$l[1]],'public'=>false,'show_ui'=>true,'show_in_rest'=>true,'supports'=>['title','editor','thumbnail','revisions'],'capability_type'=>'post','map_meta_cap'=>true,'menu_icon'=>'dashicons-groups']);}
    register_taxonomy_for_object_type('awsw_program','awsw_photo');
    register_taxonomy('awsw_report_type','awsw_report',['label'=>'Report type','public'=>true,'hierarchical'=>true,'show_in_rest'=>true]);
    foreach(['financial'=>'Financial reports','project'=>'Project reports','registration'=>'Registration documents'] as $s=>$n){if(!term_exists($s,'awsw_report_type')){wp_insert_term($n,'awsw_report_type',['slug'=>$s]);}}
    if(!get_option('awsw_editorial_categories')){foreach(['Organization News','Field Updates','Community Stories','Education','Health','Clean Water','Giving and Transparency'] as $n){if(!term_exists($n,'category')){wp_insert_term($n,'category');}}update_option('awsw_editorial_categories',1);}
});
function awsw_page_intro($eyebrow,$title,$text){return '<div class="awsw-editorial-intro"><span class="awsw-eyebrow">'.esc_html($eyebrow).'</span><h2>'.wp_kses($title,['em'=>[],'br'=>[]]).'</h2><p class="awsw-lead">'.esc_html($text).'</p></div>';}
function awsw_faq_items($items){$html='<div class="awsw-faq-items">';foreach($items as $f){$html.='<details><summary>'.esc_html(awsw_t($f[0],$f[1])).'</summary><p>'.esc_html(awsw_t($f[2],$f[3])).'</p></details>';}return $html.'</div>';}
function awsw_participation_routes(){return ['volunteer'=>['volunteer','Volunteer your time','اپنا وقت دیں','Share your skills and register your general interest.','اپنی مہارت بانٹیں اور عمومی دلچسپی درج کرائیں۔','users'],'partnerships'=>['partnerships','Partner with purpose','بامقصد شراکت','Explore sponsorship, in-kind support or employee volunteering.','سرپرستی، اشیاء کی مدد یا ملازمین کی رضاکارانہ خدمت۔','heart'],'in-kind'=>['in-kind','Give useful essentials','ضروری اشیاء کی مدد','Discuss appropriate supplies before arranging a collection.','اشیاء جمع کرنے سے پہلے موزوں ضروریات پر بات کریں۔','food'],'contact'=>['contact','Start a conversation','بات چیت کا آغاز','Ask the team how your support could help.','ٹیم سے پوچھیں کہ آپ کی مدد کہاں کارآمد ہو سکتی ہے۔','arrow']];}
add_shortcode('awsw_get_involved',function(){
    $h=awsw_page_intro(awsw_t('YOUR NEXT STEP, WITH PURPOSE','آپ کا اگلا قدم، بامقصد'),awsw_t('There’s more than one<br><em>way to make a difference.</em>','خدمت کا صرف ایک راستہ نہیں۔<br><em>اپنا طریقہ منتخب کریں۔</em>'),awsw_t('Time, skills, supplies or collaboration: choose a route that suits you. The team reviews each inquiry before agreeing next steps.','وقت، مہارت، اشیاء یا تعاون—اپنے لیے موزوں راستہ اپنائیں۔ اگلے مراحل سے پہلے ٹیم ہر درخواست کا جائزہ لے گی۔'));
    $h.='<div class="awsw-route-list">';foreach(awsw_participation_routes() as $r){$h.='<article>'.awsw_icon($r[5]).'<div><h3>'.esc_html(awsw_t($r[1],$r[2])).'</h3><p>'.esc_html(awsw_t($r[3],$r[4])).'</p></div>'.awsw_button(awsw_t('Explore','مزید جانیں'),awsw_url($r[0].'/'),'awsw-outline').'</article>';}return $h.'</div>';
});
add_shortcode('awsw_team',function(){
    $h=awsw_page_intro(awsw_t('PEOPLE & ACCOUNTABILITY','ٹیم اور جواب دہی'),awsw_t('Service with responsibility.','ذمہ داری کے ساتھ خدمت۔'),awsw_t('Leadership, responsibilities and governance information are published only after organizational approval.','قیادت، ذمہ داریوں اور انتظام کی معلومات ادارے کی منظوری کے بعد شائع ہوتی ہیں۔'));
    $q=get_posts(['post_type'=>'awsw_member','post_status'=>'publish','numberposts'=>50]);if(!$q){$h.=awsw_empty('Approved team profiles and photographs have not been supplied. No people or credentials are invented.','منظور شدہ ٹیم پروفائل اور تصاویر فراہم نہیں کی گئیں۔ کسی فرد یا قابلیت کا فرضی ذکر نہیں کیا جاتا۔');}else{$h.='<div class="awsw-grid">';foreach($q as $p){$h.='<article class="awsw-card">'.awsw_cover($p->ID).'<div class="awsw-card-body"><h3>'.esc_html(awsw_post_title($p->ID)).'</h3><span class="awsw-status">'.esc_html(awsw_field($p->ID,'role',get_post_meta($p->ID,'_awsw_role',true))).'</span>'.wp_kses_post(awsw_field($p->ID,'content',$p->post_content)).'</div></article>';}$h.='</div>';}
    $h.='<h2>'.esc_html(awsw_t('Governance & accountability','انتظام اور جواب دہی')).'</h2><p>'.esc_html(awsw_setting('team')?:awsw_t('Approved governance information is awaiting publication. The organization will identify accountable roles and review responsibilities here.','منظور شدہ انتظامی معلومات شائع ہونا باقی ہیں۔ ادارہ ذمہ دار کردار اور جائزے کی ذمہ داریاں یہاں بتائے گا۔')).'</p>';return $h.awsw_button(awsw_t('Transparency & reports','شفافیت اور رپورٹس'),awsw_url('transparency/'));
});
add_shortcode('awsw_volunteer_overview',function(){
    $h=awsw_page_intro(awsw_t('TIME WELL GIVEN','بامقصد وقت'),awsw_t('Bring your skills.<br><em>Grow the good.</em>','اپنی مہارت ساتھ لائیں۔<br><em>بھلائی بڑھائیں۔</em>'),awsw_t('No specific vacancies are currently published. Our general-interest application lets the team understand your skills and availability, without promising a placement.','فی الحال مخصوص مواقع شائع نہیں ہوئے۔ عمومی دلچسپی کی درخواست سے ٹیم آپ کی مہارت اور دستیابی سمجھے گی؛ جگہ کی ضمانت نہیں دی جاتی۔'));
    $h.='<div class="awsw-three-steps">';foreach([['01','Choose a focus','شعبہ منتخب کریں','Food, learning, water, medical support, or suitable remote skills.','خوراک، تعلیم، پانی، طبی مدد یا موزوں آن لائن مہارت۔'],['02','Share your availability','دستیابی بتائیں','Tell us when and how you can help. No identity documents are requested.','وقت اور طریقہ بتائیں۔ شناختی دستاویزات درکار نہیں۔'],['03','Team review & orientation','ٹیم کا جائزہ اور رہنمائی','Staff review suitability and safeguarding needs before discussing any role.','عملہ کردار پر بات کرنے سے پہلے موزونیت اور حفاظتی ضروریات کا جائزہ لے گا۔']] as $s){$h.='<article><span>'.esc_html($s[0]).'</span><h3>'.esc_html(awsw_t($s[1],$s[2])).'</h3><p>'.esc_html(awsw_t($s[3],$s[4])).'</p></article>';}$h.='</div><h2>'.esc_html(awsw_t('Care comes with responsibility','خدمت کے ساتھ ذمہ داری')).'</h2><p>'.esc_html(awsw_t('Respect privacy and dignity, follow staff guidance, keep agreed commitments, and do not photograph or share beneficiary information without approval.','رازداری اور عزت کا خیال رکھیں، عملے کی ہدایات پر چلیں، طے شدہ ذمہ داری پوری کریں اور منظوری کے بغیر تصاویر یا مستحقین کی معلومات شیئر نہ کریں۔')).'</p>';
    $h.=awsw_faq_items([['Can I help remotely?','کیا آن لائن مدد ہو سکتی ہے؟','You can indicate a remote preference; suitability depends on real needs and staff review.','آپ آن لائن ترجیح بتا سکتے ہیں؛ موزونیت حقیقی ضرورت اور عملے کے جائزے پر منحصر ہے۔'],['Is an application a confirmed placement?','کیا درخواست سے جگہ کی تصدیق ہوتی ہے؟','No. The team reviews each application before discussing a suitable opportunity.','نہیں۔ ٹیم موزوں موقع پر بات کرنے سے پہلے ہر درخواست کا جائزہ لیتی ہے۔']]);return $h.awsw_button(awsw_t('Start your application','درخواست شروع کریں'),awsw_url('volunteer-application/'));
});
add_shortcode('awsw_assistance_intro',function(){return '<p class="awsw-lead">'.esc_html(awsw_t('Tell us what support you need, in your own words.','اپنے الفاظ میں بتائیں کہ آپ کو کس مدد کی ضرورت ہے۔')).'</p><p>'.esc_html(awsw_t('This initial request is private. Share only basic contact details and a short description. Authorized staff will review it against available resources; submission does not guarantee assistance. This form is not an emergency service.','یہ ابتدائی درخواست نجی ہے۔ صرف بنیادی رابطہ اور مختصر تفصیل دیں۔ مجاز عملہ دستیاب وسائل کے مطابق جائزہ لے گا؛ مدد کی ضمانت نہیں۔ یہ ہنگامی خدمت نہیں ہے۔')).'</p>';});
add_shortcode('awsw_partnership_intro',function(){return awsw_page_intro(awsw_t('COLLABORATION, WITH CARE','ہمدردی کے ساتھ تعاون'),awsw_t('A shared purpose.<br><em>A practical partnership.</em>','مشترکہ مقصد۔<br><em>عملی شراکت۔</em>'),awsw_t('Discuss campaign sponsorship, appropriate in-kind supplies or employee volunteering. Every arrangement is reviewed for fit, responsibilities and transparent reporting. No partner endorsements are implied.','مہم کی سرپرستی، موزوں اشیاء یا ملازمین کی رضاکارانہ خدمت پر بات کریں۔ ہر تعاون میں موزونیت، ذمہ داری اور شفاف رپورٹنگ کا جائزہ لیا جاتا ہے۔ کسی ادارے کی توثیق کا دعویٰ نہیں۔'));});
add_shortcode('awsw_in_kind',function(){return awsw_page_intro(awsw_t('THOUGHTFUL, USEFUL SUPPORT','سوچ سمجھ کر کارآمد مدد'),awsw_t('Give what’s needed.<br><em>Start with a conversation.</em>','ضرورت کے مطابق دیں۔<br><em>پہلے بات کریں۔</em>'),awsw_t('Please contact the team before collecting goods. Appropriate supplies, quality, transport, storage and distribution arrangements must be agreed first. Unrequested or unsuitable items can create additional costs.','اشیاء جمع کرنے سے پہلے ٹیم سے رابطہ کریں۔ موزوں سامان، معیار، نقل و حمل، ذخیرہ اور تقسیم پہلے طے کریں۔ غیر ضروری یا ناموزوں اشیاء مزید اخراجات پیدا کر سکتی ہیں۔')).awsw_button(awsw_t('Discuss in-kind support','اشیاء کی مدد پر بات کریں'),awsw_url('partnerships/'));});
function awsw_blog_query($args=[]){$sample=get_page_by_path('hello-world',OBJECT,'post');return new WP_Query(array_merge(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>9,'post__not_in'=>$sample?[$sample->ID]:[]],$args));}
function awsw_blog_cards($args=[]){$q=awsw_blog_query($args);if(!$q->have_posts()){return awsw_empty('Reviewed articles will appear here after publication. No fictional field reports are published.','جائزہ شدہ مضامین اشاعت کے بعد یہاں نظر آئیں گے۔ فرضی عملی رپورٹس شائع نہیں ہوتیں۔');}$h='<div class="awsw-blog-grid">';foreach($q->posts as $p){$h.='<article class="awsw-card">'.awsw_cover($p->ID).'<div class="awsw-card-body"><time datetime="'.esc_attr(get_the_date('c',$p)).'">'.esc_html(get_the_date('j M Y',$p)).'</time><h3><a href="'.esc_url(add_query_arg('lang',awsw_lang(),get_permalink($p))).'">'.esc_html(awsw_post_title($p->ID)).'</a></h3><p>'.esc_html(awsw_field($p->ID,'excerpt',awsw_excerpt($p))).'</p><span class="awsw-small">'.esc_html(get_the_author_meta('display_name',$p->post_author)).'</span></div></article>';}$h.='</div>';if($q->max_num_pages>1){$h.='<nav class="awsw-pagination" aria-label="'.esc_attr(awsw_t('Article pages','مضامین کے صفحات')).'">';for($n=1;$n<=$q->max_num_pages;$n++){$h.='<a href="'.esc_url(add_query_arg('article_page',$n)).'">'.$n.'</a> ';}$h.='</nav>';}return $h;}
add_shortcode('awsw_blog',function($attrs){$a=shortcode_atts(['latest'=>'0'],$attrs);if($a['latest']==='1'){return awsw_blog_cards(['posts_per_page'=>3]);}$search=sanitize_text_field(wp_unslash($_GET['article_search']??''));$topic=absint($_GET['topic']??0);$h='<form class="awsw-filters" method="get"><input type="hidden" name="lang" value="'.esc_attr(awsw_lang()).'"><label>'.esc_html(awsw_t('Search insights','مضامین تلاش کریں')).'<input type="search" name="article_search" value="'.esc_attr($search).'"></label><label>'.esc_html(awsw_t('Category','زمرہ')).'<select name="topic"><option value="0">'.esc_html(awsw_t('All categories','تمام زمرے')).'</option>';foreach(get_categories(['hide_empty'=>false]) as $c){$h.='<option value="'.(int)$c->term_id.'" '.selected($topic,$c->term_id,false).'>'.esc_html(awsw_category_label($c->name)).'</option>';}$h.='</select></label><button class="awsw-button">'.esc_html(awsw_t('Search articles','مضامین تلاش کریں')).'</button></form>';return $h.awsw_blog_cards(['s'=>$search,'cat'=>$topic,'paged'=>max(1,absint($_GET['article_page']??1))]);});
function awsw_category_label($en){$m=['Organization News'=>'ادارے کی خبریں','Field Updates'=>'عملی کام کی خبریں','Community Stories'=>'برادری کی کہانیاں','Education'=>'تعلیم','Health'=>'صحت','Clean Water'=>'صاف پانی','Giving and Transparency'=>'عطیات اور شفافیت','Uncategorized'=>'متفرق'];return awsw_lang()==='ur'?($m[$en]??$en):$en;}
function awsw_article($id){$p=get_post($id);$h='<nav class="awsw-breadcrumbs" aria-label="'.esc_attr(awsw_t('Breadcrumbs','صفحے کا راستہ')).'"><a href="'.esc_url(awsw_url()).'">'.esc_html(awsw_t('Home','ابتدا')).'</a><span>/</span><a href="'.esc_url(awsw_url('blog/')).'">'.esc_html(awsw_t('Insights','مضامین')).'</a></nav><div class="awsw-article-meta">';foreach(get_the_category($id) as $c){$h.='<span class="awsw-status">'.esc_html(awsw_category_label($c->name)).'</span>';}$h.='<span>'.esc_html(get_the_author_meta('display_name',$p->post_author).' · '.get_the_date('j M Y',$id)).'</span></div><p class="awsw-lead">'.esc_html(awsw_field($id,'excerpt',$p->post_excerpt)).'</p>';if(has_post_thumbnail($id)){$h.=get_the_post_thumbnail($id,'large',['class'=>'awsw-article-cover']);$credit=get_post_meta($id,'_awsw_credit',true);if($credit){$h.='<p class="awsw-small">'.esc_html($credit).'</p>';}}$h.='<div class="awsw-article-body">'.apply_filters('the_content',awsw_field($id,'content',$p->post_content)).'</div><div class="awsw-share"><button class="awsw-button awsw-outline" data-share type="button">'.esc_html(awsw_t('Copy article link','مضمون کا لنک کاپی کریں')).'</button><p role="status" aria-live="polite"></p></div><h2>'.esc_html(awsw_t('More to explore','مزید مطالعہ')).'</h2>'.awsw_blog_cards(['post__not_in'=>[$id],'posts_per_page'=>3]);return $h.awsw_button(awsw_t('Support a campaign','مہم میں تعاون کریں'),awsw_url('campaigns/'));}
add_shortcode('awsw_updates_directory',function(){
    $s=sanitize_text_field(wp_unslash($_GET['update_search']??''));$program=sanitize_key($_GET['program']??'');$args=['post_type'=>'awsw_update','s'=>$s,'posts_per_page'=>12,'awsw_page_key'=>'update_page'];if(isset(awsw_programs()[$program])){$args['tax_query']=[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>$program]];}
    return '<form class="awsw-filters" method="get"><input name="lang" type="hidden" value="'.esc_attr(awsw_lang()).'"><label>'.esc_html(awsw_t('Search dated updates','تاریخ وار خبریں تلاش کریں')).'<input type="search" name="update_search" value="'.esc_attr($s).'"></label>'.awsw_program_select($program).'<button class="awsw-button">'.esc_html(awsw_t('Search','تلاش')).'</button></form>'.awsw_updates($args);
});
function awsw_program_select($current=''){ $h='<label>'.esc_html(awsw_t('Program','شعبہ')).'<select name="program"><option value="">'.esc_html(awsw_t('All programs','تمام شعبے')).'</option>';foreach(awsw_programs() as $s=>$p){$h.='<option value="'.esc_attr($s).'" '.selected($current,$s,false).'>'.esc_html(awsw_t($p[0],$p[1])).'</option>';}return $h.'</select></label>';}
add_shortcode('awsw_reports',function(){
    $year=absint($_GET['report_year']??0);$type=sanitize_key($_GET['report_type']??'');$h='<form class="awsw-filters" method="get"><input name="lang" type="hidden" value="'.esc_attr(awsw_lang()).'"><label>'.esc_html(awsw_t('Publication year','سالِ اشاعت')).'<select name="report_year"><option value="0">'.esc_html(awsw_t('All years','تمام سال')).'</option>';global $wpdb;$years=$wpdb->get_col("SELECT DISTINCT YEAR(post_date) FROM {$wpdb->posts} WHERE post_type='awsw_report' AND post_status='publish' ORDER BY post_date DESC");foreach($years as $y){$h.='<option value="'.(int)$y.'" '.selected($year,$y,false).'>'.(int)$y.'</option>';}$h.='</select></label><label>'.esc_html(awsw_t('Report type','رپورٹ کی قسم')).'<select name="report_type"><option value="">'.esc_html(awsw_t('All types','تمام اقسام')).'</option>';foreach(['financial'=>['Financial reports','مالی رپورٹس'],'project'=>['Project reports','منصوبوں کی رپورٹس'],'registration'=>['Registration documents','رجسٹریشن دستاویزات']] as $s=>$l){$h.='<option value="'.esc_attr($s).'" '.selected($type,$s,false).'>'.esc_html(awsw_t(...$l)).'</option>';}$h.='</select></label><button class="awsw-button">'.esc_html(awsw_t('Filter reports','رپورٹس دیکھیں')).'</button></form>';
    $args=['post_type'=>'awsw_report','posts_per_page'=>12,'awsw_page_key'=>'report_page'];if($year){$args['date_query']=[['year'=>$year]];}if(in_array($type,['financial','project','registration'],true)){$args['tax_query']=[['taxonomy'=>'awsw_report_type','field'=>'slug','terms'=>$type]];}return $h.awsw_updates($args).'<p>'.esc_html(awsw_t('Questions about a report? Ask the team for clarification.','رپورٹ کے بارے میں سوال ہو تو ٹیم سے وضاحت طلب کریں۔')).' <a href="'.esc_url(awsw_url('contact/')).'">'.esc_html(awsw_t('Contact us','رابطہ کریں')).'</a></p>';
});
add_shortcode('awsw_gallery',function(){
    $program=sanitize_key($_GET['program']??'');$args=['post_type'=>'awsw_photo','post_status'=>'publish','posts_per_page'=>60,'meta_key'=>'_awsw_approved','meta_value'=>'1'];if(isset(awsw_programs()[$program])){$args['tax_query']=[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>$program]];}$q=new WP_Query($args);$h='<p>'.esc_html(awsw_t('Only approved, consent-appropriate photographs are displayed. No beneficiary information should be disclosed without authorization.','صرف منظور شدہ اور موزوں رضامندی والی تصاویر دکھائی جاتی ہیں۔ اجازت کے بغیر مستحقین کی معلومات ظاہر نہیں ہونی چاہئیں۔')).'</p><form class="awsw-filters" method="get"><input name="lang" type="hidden" value="'.esc_attr(awsw_lang()).'">'.awsw_program_select($program).'<button class="awsw-button">'.esc_html(awsw_t('Filter gallery','تصاویر منتخب کریں')).'</button></form>';
    $photos='';foreach($q->posts as $p){if(!has_post_thumbnail($p)){continue;}$full=get_the_post_thumbnail_url($p,'full');$caption=awsw_post_title($p->ID).' · '.get_the_date('j M Y',$p);$photos.='<figure><a data-gallery href="'.esc_url($full).'" data-caption="'.esc_attr($caption).'">'.get_the_post_thumbnail($p,'medium_large',['loading'=>'lazy','alt'=>awsw_post_title($p->ID)]).'</a><figcaption>'.esc_html($caption).'</figcaption></figure>';}
    return $h.($photos?'<div class="awsw-gallery-grid">'.$photos.'</div>':awsw_empty('Approved gallery photographs have not yet been supplied.','منظور شدہ تصاویر ابھی فراہم نہیں کی گئیں۔'));
});
add_shortcode('awsw_impact_extended',function(){
    $period=sanitize_text_field(wp_unslash($_GET['period']??''));global $wpdb;$periods=$wpdb->get_col("SELECT DISTINCT m.meta_value FROM {$wpdb->postmeta} m INNER JOIN {$wpdb->posts} p ON p.ID=m.post_id WHERE p.post_type='awsw_metric' AND p.post_status='publish' AND m.meta_key='_awsw_period' AND m.meta_value<>'' ORDER BY m.meta_value DESC");$h='';if($periods){$h.='<form class="awsw-filters" method="get"><input type="hidden" name="lang" value="'.esc_attr(awsw_lang()).'"><label>'.esc_html(awsw_t('Reporting period','رپورٹنگ کی مدت')).'<select name="period"><option value="">'.esc_html(awsw_t('All reporting periods','تمام مدتیں')).'</option>';foreach($periods as $p){$h.='<option '.selected($period,$p,false).'>'.esc_html($p).'</option>';}$h.='</select></label><button class="awsw-button">'.esc_html(awsw_t('Apply period','مدت منتخب کریں')).'</button></form>';}
    $h.=do_shortcode('[awsw_metrics]').'<h2>'.esc_html(awsw_t('How we measure progress','ہم پیش رفت کیسے جانچتے ہیں')).'</h2><p>'.esc_html(awsw_t('Each published metric needs a definition, reporting period, evidence reference and an authorized editor. Financial totals and project delivery are separate measures. Unsupported charts are not shown.','ہر شائع شدہ پیمانے کے لیے تعریف، مدت، ثبوت کا حوالہ اور مجاز مدیر ضروری ہیں۔ مالی رقم اور عملی کام الگ پیمانے ہیں۔ غیر ثابت شدہ چارٹ نہیں دکھائے جاتے۔')).'</p><h2>'.esc_html(awsw_t('Completed project highlights','مکمل منصوبوں کی جھلکیاں')).'</h2>'.awsw_campaign_cards(['meta_key'=>'_awsw_status','meta_value'=>'completed','posts_per_page'=>6]).'<h2>'.esc_html(awsw_t('Explore by program','شعبے کے لحاظ سے دیکھیں')).'</h2>'.do_shortcode('[awsw_programs]');return $h.awsw_button(awsw_t('Supporting reports','متعلقہ رپورٹس'),awsw_url('transparency/'));
});
function awsw_faq_groups(){return [
'donations'=>['Donations','عطیات',[['Can I choose a campaign?','کیا مہم منتخب کی جا سکتی ہے؟','Choose an active campaign or general fund. Each published campaign explains its intended use of funds.','جاری مہم یا عمومی فنڈ منتخب کریں۔ شائع شدہ مہم میں رقم کا متوقع استعمال بیان ہوتا ہے۔']]],
'verification'=>['Bank transfer verification','بینک ٹرانسفر کی تصدیق',[['Is a screenshot a confirmed donation?','کیا اسکرین شاٹ تصدیق شدہ عطیہ ہے؟','No. Staff must match the transfer to the bank statement. Pending submissions do not count in public totals.','نہیں۔ عملہ بینک اسٹیٹمنٹ سے ٹرانسفر ملائے گا۔ زیرِ تصدیق درخواستیں عوامی رقم میں شامل نہیں۔'],['How do I check status?','حالت کیسے معلوم ہو گی؟','Use the private emailed link, or request a new one with your reference and donation email on Donation Status.','ای میل کا نجی لنک استعمال کریں یا عطیے کی حالت کے صفحے سے اپنے حوالے اور ای میل کے ساتھ نیا لنک حاصل کریں۔']]],
'campaigns'=>['Campaigns','مہمات',[['Does reaching a target complete a project?','کیا ہدف پورا ہونے سے منصوبہ مکمل ہو جاتا ہے؟','No. Delivery milestones and dated updates explain operational progress independently.','نہیں۔ عملی مراحل اور تاریخ وار خبریں الگ پیش رفت بیان کرتی ہیں۔']]],
'volunteering'=>['Volunteering','رضاکارانہ خدمت',[['Are there guaranteed placements?','کیا جگہ کی ضمانت ہے؟','No. The general-interest application is reviewed against actual needs and suitable roles.','نہیں۔ عمومی دلچسپی کی درخواست حقیقی ضروریات اور موزوں کردار کے مطابق دیکھی جاتی ہے۔']]],
'assistance'=>['Assistance requests','معاونت کی درخواستیں',[['Does an application guarantee help?','کیا درخواست سے مدد یقینی ہے؟','No. Authorized staff review basic requests against available resources. Do not upload identity or medical documents.','نہیں۔ مجاز عملہ دستیاب وسائل کے مطابق بنیادی درخواست دیکھتا ہے۔ شناختی یا طبی دستاویزات اپلوڈ نہ کریں۔']]],
'reports'=>['Reports & transparency','رپورٹس اور شفافیت',[['Where can I find reports?','رپورٹس کہاں ملیں گی؟','The Transparency page lists reviewed documents with dates, year and type filters. Missing reports are marked honestly.','شفافیت کے صفحے پر جائزہ شدہ دستاویزات تاریخ، سال اور قسم کے ساتھ ملتی ہیں۔ غیر موجود رپورٹس کی واضح نشاندہی ہوتی ہے۔']]]];}
