 'water'=>['Safe water. Everyday dignity.','محفوظ پانی۔ روزمرہ عزت۔','Reliable clean water is an essential need. Project responses must be assessed for local suitability, maintenance and safe delivery before a campaign is opened.','قابلِ اعتماد صاف پانی بنیادی ضرورت ہے۔ مہم شروع کرنے سے پہلے مقامی موزونیت، دیکھ بھال اور محفوظ فراہمی کا جائزہ ضروری ہے۔','Assess local needs, obtain a reviewed technical plan where needed, coordinate implementation and document checks and maintenance responsibility.','مقامی ضرورت کا جائزہ، ضرورت کے مطابق جائزہ شدہ تکنیکی منصوبہ، عمل درآمد اور معیار و دیکھ بھال کی ذمہ داری کا تعین۔'],
 'medical'=>['Care, with dignity and privacy.','عزت اور رازداری کے ساتھ علاج۔','Treatment costs and access barriers can affect families. Initial requests use minimal information; authorized staff review needs and available support without publicly exposing health records.','علاج کے اخراجات اور رسائی کی رکاوٹیں خاندانوں کو متاثر کر سکتی ہیں۔ ابتدائی درخواست میں کم سے کم معلومات لی جاتی ہیں؛ مجاز عملہ صحت کا ریکارڈ ظاہر کیے بغیر جائزہ لیتا ہے۔','Receive a basic private request, assess suitable support, coordinate approved assistance and report activity without sensitive beneficiary details.','بنیادی نجی درخواست، موزوں معاونت کا جائزہ، منظور شدہ مدد اور حساس معلومات کے بغیر کام کی رپورٹنگ۔']];
 $d=$specific[$s];$h='<div class="awsw-program-hero"><div>'.awsw_icon($s==='food'?'food':$s).'<h2>'.esc_html(awsw_t($d[0],$d[1])).'</h2><p>'.esc_html(awsw_t($p[2],$p[3])).'</p></div>'.awsw_cover(0).'</div><div class="awsw-editorial-columns"><section><span class="awsw-eyebrow">'.esc_html(awsw_t('THE NEED & INTENDED RESPONSE','ضرورت اور متوقع معاونت')).'</span><h2>'.esc_html(awsw_t('Support shaped by need.','ضرورت کے مطابق مدد۔')).'</h2><p>'.esc_html(awsw_t($d[2],$d[3])).'</p></section><section><span class="awsw-eyebrow">'.esc_html(awsw_t('PLANNED ACTIVITIES','متوقع سرگرمیاں')).'</span><h2>'.esc_html(awsw_t('Practical steps, clear records.','عملی مراحل، واضح ریکارڈ۔')).'</h2><p>'.esc_html(awsw_t($d[4],$d[5])).'</p></section></div>';if($a['part']==='intro'){return $h;}if($a['part']==='dynamic'){$h='';}$h.='<h2>'.esc_html(awsw_t('Related campaigns','متعلقہ مہمات')).'</h2>'.awsw_campaign_cards(['tax_query'=>[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>$s]]]).'<h2>'.esc_html(awsw_t('Dated project updates','تاریخ وار خبریں')).'</h2>'.awsw_updates(['post_type'=>'awsw_update','tax_query'=>[['taxonomy'=>'awsw_program','field'=>'slug','terms'=>$s]]]).'<h2>'.esc_html(awsw_t('Helpful answers','مددگار جوابات')).'</h2>'.awsw_faq_items([['Is this a confirmed current activity?','کیا یہ فی الحال تصدیق شدہ سرگرمی ہے؟','This page explains the intended program approach. Only published campaigns and dated updates establish approved current work.','یہ صفحہ متوقع طریقۂ کار بتاتا ہے۔ منظور شدہ موجودہ کام کی وضاحت صرف شائع شدہ مہمات اور تاریخ وار خبروں سے ہوتی ہے۔'],['How can I request support?','معاونت کی درخواست کیسے دوں؟','Use Request Assistance and share only basic contact information and a short description. Support depends on review and resources.','معاونت کی درخواست میں بنیادی رابطہ اور مختصر تفصیل دیں۔ مدد جائزے اور وسائل پر منحصر ہے۔']]);return $h.'<div class="awsw-actions">'.awsw_button(awsw_t('Support this work','اس کام میں تعاون کریں'),awsw_url('donate/')).awsw_button(awsw_t('Volunteer your skills','اپنی مہارت دیں'),awsw_url('volunteer/'),'awsw-outline').'</div>';
