add_shortcode('awsw_story_links',function(){return '<h2>'.esc_html(awsw_t('Story & timeline','کہانی اور تاریخ وار مراحل')).'</h2><p>'.esc_html(awsw_t('Approved founding dates and historical milestones are awaiting organization review. No timeline dates or past activities are invented. Add the verified story here using the page editor.','ابتدائی تاریخوں اور تاریخی مراحل کا ادارے کا جائزہ باقی ہے۔ کوئی تاریخ یا سابقہ سرگرمی فرض نہیں کی گئی۔ تصدیق شدہ کہانی صفحے کے مدیر سے شامل کریں۔')).'</p><div class="awsw-actions">'.awsw_button(awsw_t('Team & governance','ٹیم اور انتظام'),awsw_url('team/'),'awsw-outline').awsw_button(awsw_t('Accountability & reports','جواب دہی اور رپورٹس'),awsw_url('transparency/'),'awsw-outline').'</div>';});
function awsw_editable_static_sections($content){
    $static=['awsw_get_involved','awsw_volunteer_overview','awsw_assistance_intro','awsw_partnership_intro','awsw_in_kind'];
    $needed=false;foreach($static as $tag){if(str_contains($content,'['.$tag.']')){$needed=true;}}
    if(!$needed){return $content;}
    $plain=str_replace(['<!-- wp:shortcode -->','<!-- /wp:shortcode -->'],'',$content);
    $parts=preg_split('/(\[awsw_[^\]]+\])/', $plain,-1,PREG_SPLIT_DELIM_CAPTURE);$html='';
    foreach($parts as $part){if(!trim($part)){continue;}$expand=false;foreach($static as $tag){if($part==='['.$tag.']'){$expand=true;}}$html.=$expand?'<!-- wp:html -->'.do_shortcode($part).'<!-- /wp:html -->':'<!-- wp:shortcode -->'.$part.'<!-- /wp:shortcode -->';}
    return $html;
}

function awsw_excerpt($post){$p=get_post($post);return $p->post_excerpt ?: wp_trim_words(wp_strip_all_tags(strip_shortcodes($p->post_content)),28);}
function awsw_update_metadata($id){
    $h='<dl class="awsw-update-meta">';foreach(['location'=>['General location','عمومی علاقہ'],'milestone_status'=>['Delivery milestone','عملی مرحلہ'],'period'=>['Reporting period','رپورٹنگ کی مدت']] as $key=>$label){$value=get_post_meta($id,'_awsw_'.$key,true);if($value){$h.='<dt>'.esc_html(awsw_t(...$label)).'</dt><dd>'.esc_html(awsw_field($id,$key,$value)).'</dd>';}}
    $report=absint(get_post_meta($id,'_awsw_related_report',true));if($report&&get_post_type($report)==='awsw_report'&&get_post_status($report)==='publish'){$h.='<dt>'.esc_html(awsw_t('Supporting report','متعلقہ رپورٹ')).'</dt><dd><a href="'.esc_url(add_query_arg('lang',awsw_lang(),get_permalink($report))).'">'.esc_html(awsw_post_title($report)).'</a></dd>';}return $h.'</dl>';
}
// Internal editorial records are not a public REST gallery. Public rendering applies approval rules.
add_filter('rest_pre_dispatch',function($result,$server,$request){
    if(preg_match('#^/wp/v2/(awsw_photo|awsw_member)(?:/|$)#',$request->get_route())&&!current_user_can('edit_posts')){return new WP_Error('awsw_editorial_private','Use the approved public gallery or team page.',['status'=>403]);}
    return $result;
},10,3);
add_filter('rest_post_search_query',function($args){
    if(!current_user_can('edit_posts')&&isset($args['post_type'])){$args['post_type']=array_values(array_diff((array)$args['post_type'],['awsw_photo','awsw_member']));if(!$args['post_type']){$args['post__in']=[0];}}
    return $args;
});
